schema_json:
{
  "$defs": {
    "BairroEntry": {
      "description": "One bairro / localidade entry with optional interview count.",
      "properties": {
        "name": {
          "description": "Bairro / localidade name, verbatim as written in the PDF.",
          "title": "Name",
          "type": "string"
        },
        "n_entrevistas": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Number of interviews allocated to this bairro, if stated. Null when not reported. For pollsters using regional structure (RJ-style with Total Região), report the per-bairro count, not the region total.",
          "title": "N Entrevistas"
        },
        "distrito": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Distrito / region the bairro belongs to, if the PDF organizes bairros by distrito (e.g., RJ-style REGIÃO/Distrito structure). Null otherwise.",
          "title": "Distrito"
        }
      },
      "required": [
        "name"
      ],
      "title": "BairroEntry",
      "type": "object"
    },
    "CoverageClassResolved": {
      "enum": [
        "full_municipality",
        "urban_only",
        "urban_plus_selected_rural",
        "specific_neighborhoods",
        "rural_only",
        "cross_municipal",
        "not_realized",
        "other",
        "unclear"
      ],
      "title": "CoverageClassResolved",
      "type": "string"
    }
  },
  "description": "Coverage detail from per-poll bairro/município complement PDF.",
  "properties": {
    "pesquisa_realized": {
      "description": "True normally. False ONLY when the PDF is the 'PESQUISA NÃO REALIZADA' stamp (poll was cancelled). When false, all other fields default to empty/zero/unclear.",
      "title": "Pesquisa Realized",
      "type": "boolean"
    },
    "coverage_class_resolved": {
      "$ref": "#/$defs/CoverageClassResolved",
      "description": "Final coverage classification from the actual bairro list. full_municipality if the list spans the major bairros of the city + rural districts; urban_only if no rural is named; specific_neighborhoods if only a small subset; not_realized if pesquisa_realized is false."
    },
    "coverage_class_evidence": {
      "default": "",
      "description": "1-2 sentence quote or paraphrase from the PDF supporting the classification.",
      "title": "Coverage Class Evidence",
      "type": "string"
    },
    "bairros": {
      "description": "All bairros / localidades listed in the PDF, deduplicated. HARD CAP at 50 entries (token budget). If more, populate the top 50 by n_entrevistas descending and record the true total in n_bairros_total. NEVER exceed 50. Empty list when the PDF is setor-microdata only with no bairro names.",
      "items": {
        "$ref": "#/$defs/BairroEntry"
      },
      "title": "Bairros",
      "type": "array"
    },
    "n_bairros_total": {
      "default": 0,
      "description": "Total distinct bairros listed in the PDF (may exceed len(bairros) if truncated). 0 when no bairros are listed.",
      "title": "N Bairros Total",
      "type": "integer"
    },
    "distritos_listed": {
      "description": "Distritos / regiões / administrative subdivisions if the PDF uses them (common in large munis like RJ, SP). Empty if the PDF doesn't structure by distrito.",
      "items": {
        "type": "string"
      },
      "title": "Distritos Listed",
      "type": "array"
    },
    "regional_structure": {
      "description": "True if the PDF organizes bairros by REGIÃO / Distrito (common in RJ, SP). False for flat bairro lists.",
      "title": "Regional Structure",
      "type": "boolean"
    },
    "setor_codes_sample": {
      "description": "Up to 10 example IBGE setor censitário codes if the PDF lists them (typically 12-15 digits). Empty for most pollsters; populated for QUAEST-style PDFs.",
      "items": {
        "type": "string"
      },
      "title": "Setor Codes Sample",
      "type": "array"
    },
    "n_setores_total": {
      "default": 0,
      "description": "Total setor codes in the PDF; 0 if not listed.",
      "title": "N Setores Total",
      "type": "integer"
    },
    "rural_included": {
      "description": "True if any rural bairro / assentamento / distrito is in the list.",
      "title": "Rural Included",
      "type": "boolean"
    },
    "rural_explicit": {
      "description": "True only if the PDF explicitly states rural inclusion (e.g., 'inclui zona rural').",
      "title": "Rural Explicit",
      "type": "boolean"
    },
    "total_interviews_distributed": {
      "default": 0,
      "description": "Sum of n_entrevistas across all bairros if reported. 0 if interview counts are not given. Should match the poll's QT_ENTREVISTADO when fully reported.",
      "title": "Total Interviews Distributed",
      "type": "integer"
    },
    "extraction_notes": {
      "default": "",
      "description": "Free-form notes on ambiguity, format unusual, or PDF truncation. Flag here if the PDF is text-thin (likely an image-only scan that needs OCR).",
      "title": "Extraction Notes",
      "type": "string"
    }
  },
  "required": [
    "pesquisa_realized",
    "coverage_class_resolved",
    "regional_structure",
    "rural_included",
    "rural_explicit"
  ],
  "title": "PollBairroDetail",
  "type": "object"
}
